window.MCA=window.MCA||{},function(){const n=window.MCA.DATA.grading;window.MCA.grading={bands:n.bands,transitional:n.transitionalGrades,standards:n.passingStandards,gradeFromPct:function(t){for(const r of n.bands)if(t>=r.min-1e-9)return r;return n.bands[n.bands.length-1]},gpFromLetter:function(t){const r=n.bands.find(n=>n.grade===t);return r?r.gp:null},isTransitional:function(t){return n.transitionalGrades.includes(t)},clampNum:function(n,t,r){return n=parseFloat(n),isNaN(n)&&(n=0),void 0!==t&&(n=Math.max(t,n)),void 0!==r&&(n=Math.min(r,n)),n},fmt:function(n){return window.MCA.util.round2(n).toString()},degreeClass:function(t){for(const r of n.degreeClass)if(t>=r.minCgpa)return r.class;return"Not yet eligible"},renderGradeScale:function(){const t=n.bands,r=t.map((n,r)=>{if("O"===n.grade)return"90-100";const a=t[r-1];return`${n.min}-${a.min-1}`});return`\n    <div class="card grade-scale-card">\n      <h2>Grade Scale Reference</h2>\n\n      <div class="grade-scale-table-wrap">\n        <table class="grade-scale-table">\n          <thead>\n            <tr>\n              <th>Letter Grade</th>\n              ${t.map(n=>`\n                <th>${n.grade}</th>\n              `).join("")}\n            </tr>\n          </thead>\n\n          <tbody>\n            <tr>\n              <th>Grade Point</th>\n              ${t.map(n=>`\n                <td>${n.gp}</td>\n              `).join("")}\n            </tr>\n\n            <tr>\n              <th>% of Marks<br>secured</th>\n              ${r.map(n=>`\n                <td>${n}</td>\n              `).join("")}\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  `}}}();
